        assertEquals(0.5, result.getAzimuth(), 0.01);
    }

    @Test
    public void calculateSolarPosition_Atomically_ReturnsCorrectElevation() {
        when(date.withZoneSameInstant(ZoneOffset.UTC)).thenReturn(date);
